"""Build matching Runtime and observed ublk daemon; no target deployment or SDK."""
import argparse
import base64
import hashlib
import json
import os
from pathlib import Path
import platform
import shutil
import socket
import subprocess
import sys
import zlib

# The delivery generator inserts exact published source and reviewed helpers.
PAYLOAD = {'core-source.tar.gz': {'bytes': 2412779, 'sha256': '555689efe47ab412e92a6deabc944431693664a497dbcadac85a9ed66653dcc0', 'data': ''}, 'archive-tests-lib.rs': {'bytes': 3153, 'sha256': '119be80d80d5b06ac71bb38d4ab22099a9609cfdb54e08cffb0e63ee989ae22f', 'data': ''}, 'archive-tests-Cargo.toml': {'bytes': 270, 'sha256': 'd6412a9de0c77e8b9fc20e1ba3d07e5af896696c181ec68ff39ca176808b22d2', 'data': 'eNo9T9EOgjAMfDfhJ/asC5sk4sO+hBBTtyIT2Mg2Icb473bE8NTe9Xq9NjPoAR7YFgcHEyrmINkFTxB0n6v2LgXQiRWHBUO03ilWcsFLItDYtBGylIJws/owRDLMbs1o71RmSL1i1PMQs8TgjM6g0xYjjcG9e78qpsiRi1KSJPYgiciQXwnTrt6w5KKuiEg4zZ0dKas6c3nZokQMBtVnj7j5SVmzY4eQXgGjapjBQC+x9vvX355x14oq3/oB4eJQDw=='}, 'archive-tests-Cargo.lock': {'bytes': 13195, 'sha256': '54387ea8166d814076085e7ffde9a0ce5f8cdc7fcadaf42da7a2ad7618a77a7b', 'data': ''}, 'observer-tests-lib.rs': {'bytes': 75, 'sha256': '4ef46dfe6ae685cf66846d54e14791fc02d3c66951faec8b2764efadc88eef84', 'data': 'eNpTVoxOzMnJL9dISU1MiU/OT0nVjOVSji5ILMmwVYqPd/b3C3H1C4n3dwp2DQpzDYoPcAzxiI9XiuUqKE1SyM1PUchPKk4tKkstsuYCAJ9uGHA='}, 'observer-tests-Cargo.toml': {'bytes': 166, 'sha256': 'd05ac9120ec476bc41ef7590d993be6ab4d3f277487d9439e477673fab58ee91', 'data': 'eNodjsEOwjAMQ+/5jNxXdQMJceiXVBPq2gBlW1s1AX6fjJttyc/2LcQ1PGiGEnZyGGsRKjLUhal/qA9c3z3SIMTCCJpwrsWhNaOxCJSy/P1kpxHBf2tfWZHK81teZmhBng5Vmq51n6hRSVRiJp5BJxLdXnwAnPLMeL4iCO3tnjc9405muhwzP7HyNm0='}, 'observer-tests-Cargo.lock': {'bytes': 11314, 'sha256': '44cc7762ee44af2d0ce455b58e2d26c525dff5827f7aaa192050821fee8f152e', 'data': ''}}
RELEASE = {'observerSourceSha256': 'f77bf7e35d90676f91474e92ec5f77c868bf16a3ec77f5e6b6b17fc5f935b750', 'published': True, 'coreCommit': '445f11c5be774c09e3534e07913d2a2b7c3bfa7e', 'localCommit': '6aaf59d7be41a6163aab62cd20a3862355224fad', 'tree': '199589d0673c6404ef957e8436f3e55b5fed99b1'}
ROOT = Path('/home/jwk/agent')
WORK = ROOT / 'builds/content-observer-release-v1'
EXPORT_HELPER_SHA = '424ddd4cb3edc36f52b79081fedbfda67fed569578df0d7a323824611d94e048'
GIB = 1024**3


def need(ok, message):
    if not ok:
        raise RuntimeError(message)


def unpack(name):
    item = PAYLOAD[name]
    data = zlib.decompress(base64.b64decode(item['data'], validate=True))
    need(len(data) == item['bytes'] and hashlib.sha256(data).hexdigest() == item['sha256'], 'Embedded source differs: ' + name)
    return data


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--run', action='store_true')
    args = parser.parse_args()
    report = {'revision': 'A-content-observer-build-v1', 'status': 'PLAN_ONLY', 'release': RELEASE,
              'SDK_called': False, 'Guest_created': False, 'servicesChanged': False, 'phases': {},
              'workDirectory': str(WORK), 'memfilePrivateCowImplemented': False,
              'pmemSnapshotHardwareAccepted': False, 'newServicesDeployed': False,
              'scope': 'Matching Runtime and observed daemon candidates; deployment and same-window collection remain separate', 'automaticUbRepublishImplemented': False}
    if not args.run:
        print(json.dumps(report, indent=2)); return 0
    made = False
    try:
        need(RELEASE.get('published') is True, 'Draft source packet is not a published release')
        need(platform.system() == 'Linux' and platform.machine() == 'aarch64' and socket.gethostname() == 'server1', 'Use ARM64 node A')
        need(os.getuid() == os.geteuid() == 1204 and os.getgid() == os.getegid() == 1205, 'Use ordinary jwk')
        caps = dict(line.split(':', 1) for line in Path('/proc/self/status').read_text().splitlines() if ':' in line)
        need(all(int(caps[k].strip(), 16) == 0 for k in ('CapInh', 'CapPrm', 'CapEff', 'CapAmb')), 'Zero capabilities required')
        need(ROOT.resolve(strict=True) == ROOT and WORK.parent.resolve(strict=True) == WORK.parent,
             'Unexpected build parent')
        need(not WORK.exists() and not WORK.is_symlink(), 'Prior candidate attempt preserved; do not rerun')
        need(shutil.disk_usage(ROOT).free >= 16 * GIB, '16 GiB initial build headroom required')
        helper = ROOT / 'A_export_real_rootfs_v1.py'
        need(helper.resolve(strict=True) == helper and helper.is_file() and helper.stat().st_size == 26588, 'Existing export helper differs')
        helper_raw = helper.read_bytes()
        need(hashlib.sha256(helper_raw).hexdigest() == EXPORT_HELPER_SHA, 'Existing export helper hash differs')
        m = {'__name__': 'verified_build_helpers'}
        exec(compile(helper_raw, str(helper), 'exec'), m)
        m['WORK'] = WORK
        os.umask(0o077); WORK.mkdir(mode=0o700); made = True
        (WORK / 'tmp').mkdir(mode=0o700)
        archive = unpack('core-source.tar.gz')
        m['ARCHIVE_SHA'] = hashlib.sha256(archive).hexdigest()
        source = m['unpack_source'](archive, WORK / 'core-source')
        need(hashlib.sha256(m['read'](source / 'Cargo.lock')).hexdigest() == m['LOCK_SHA'], 'Frozen core lock differs')
        report['imagesRebuilt'] = False
        rust = m['RUST']
        native = m['BASE'] / 'native'
        env = {'HOME': str(Path.home()), 'USER': 'jwk', 'LOGNAME': 'jwk', 'LANG': 'C.UTF-8',
               'PATH': str(rust) + ':' + str(native / 'bin') + ':/usr/local/bin:/usr/local/sbin:/usr/bin:/usr/sbin:/bin:/sbin', 'CARGO_HOME': str(m['CARGO_HOME']),
               'CARGO_TARGET_DIR': str(m['TARGET']), 'CARGO_NET_OFFLINE': 'true', 'CARGO_BUILD_JOBS': '2',
               'CARGO_INCREMENTAL': '0', 'RUSTC': str(rust / 'rustc'), 'RUSTDOC': str(rust / 'rustdoc'),
               'CARGO_PROFILE_RELEASE_LTO': 'false', 'CARGO_PROFILE_RELEASE_DEBUG': '0',
               'LIBCLANG_PATH': '/usr/lib64', 'CMAKE_BUILD_PARALLEL_LEVEL': '2', 'PROTOC': '/usr/local/bin/protoc',
               'LD_LIBRARY_PATH': str(native / 'lib') + ':' + str(native / 'fallback/lib'),
               'TMPDIR': str(WORK / 'tmp'), 'GIT_TERMINAL_PROMPT': '0', 'GIT_CONFIG_NOSYSTEM': '1',
               'GIT_CONFIG_GLOBAL': os.devnull, 'GIT_CEILING_DIRECTORIES': str(WORK)}
        pkg_dirs = [p for p in (native / 'lib/pkgconfig', ROOT / 'native/lib64/pkgconfig') if p.is_dir()]
        if pkg_dirs:
            env['PKG_CONFIG_PATH'] = ':'.join(map(str, pkg_dirs))
        prior_build = json.loads(m['read'](ROOT / 'builds/agentenv-native-fe63038/return.json'))
        need(prior_build.get('status') == 'THREE_CORE_BINARIES_BUILT_STAGED_NOT_DEPLOYED', 'Prior successful build receipt required')
        for key, patterns in (('ROCKSDB_LIB_DIR', ('librocksdb.*',)), ('SNAPPY_LIB_DIR', ('libsnappy.*',)),
                              ('LIBCLANG_PATH', ('libclang.so*', 'libclang-*.so*'))):
            value = prior_build.get('explicitNativeBuildDirectories', {}).get(key)
            if value:
                directory = Path(value)
                need(directory.is_absolute() and directory.resolve(strict=True) == directory and directory.is_dir()
                     and any(any(directory.glob(pattern)) for pattern in patterns), 'Prior native dependency changed: ' + key)
                env[key] = str(directory)
        env['AENV_OBSERVER_BUILD_PATCH_SHA'] = RELEASE['observerSourceSha256']
        cargo = str(rust / 'cargo')
        tests = WORK / 'archive-tests'; tests.mkdir(mode=0o700)
        (tests / 'Cargo.toml').write_bytes(unpack('archive-tests-Cargo.toml'))
        text = unpack('archive-tests-lib.rs').decode('utf-8')
        text = text.replace('__NATIVE_ARCHIVE_PATH__', str(source / 'src/sandbox/native_archive.rs'))
        (tests / 'lib.rs').write_text(text, encoding='utf-8')
        (tests / 'Cargo.lock').write_bytes(unpack('archive-tests-Cargo.lock'))
        m['run']([cargo, 'test', '--offline', '--locked', '--manifest-path', str(tests / 'Cargo.toml')],
                 'native-archive-file-lifecycle-tests', tests, env, report)
        m['run'](['/usr/bin/python3', '-I', '-B', '-m', 'unittest', 'discover', '-s',
                  str(source / 'components/ub-memory-provider/tests')],
                 'provider-protocol-and-archive-tests', source, env, report, 120)
        observer_tests = WORK / 'observer-tests'; observer_tests.mkdir(mode=0o700)
        (observer_tests / 'Cargo.toml').write_bytes(unpack('observer-tests-Cargo.toml'))
        (observer_tests / 'Cargo.lock').write_bytes(unpack('observer-tests-Cargo.lock'))
        observer = unpack('observer-tests-lib.rs').decode('utf-8').replace('__CONTENT_OBSERVER_PATH__', str(source / 'storage/overlaybd/src/rootfs_access_trace.rs'))
        (observer_tests / 'lib.rs').write_text(observer, encoding='utf-8')
        m['run']([cargo, 'test', '--offline', '--locked', '--manifest-path', str(observer_tests / 'Cargo.toml')],
                 'content-observer-source-tests', observer_tests, env, report)
        m['run']([cargo, 'build', '--release', '--offline', '--locked', '-p', 'agentenv', '--bin', 'server', '-p', 'uvm-ublk-daemon', '--bin', 'uvm-ublk-daemon', '--features', 'overlaybd/rootfs-read-trace'],
                 'build-content-observer-binaries', source, env, report)
        artifacts = WORK / 'artifacts'; artifacts.mkdir(mode=0o700)
        report['artifacts'] = {}
        for name in ('server', 'uvm-ublk-daemon'):
            binary = m['TARGET'] / 'release' / name
            data = m['read'](binary, 256 * 1024**2)
            need(data[:6] == b'\x7fELF\x02\x01' and int.from_bytes(data[18:20], 'little') == 183,
                 'Expected AArch64 candidate ELF: ' + name)
            target = artifacts / name
            with target.open('xb') as stream: stream.write(data)
            target.chmod(0o700)
            report['artifacts'][name] = {'path': str(target), 'bytes': len(data), 'sha256': hashlib.sha256(data).hexdigest()}
        report['observerSourceSha256'] = RELEASE['observerSourceSha256']
        report['providerSource'] = str(source / 'components/ub-memory-provider')
        report['status'] = 'CONTENT_OBSERVER_BINARIES_BUILT_TESTED_NOT_DEPLOYED'
    except BaseException as error:
        report.update(status='STOPPED_RELEASE_PREPARATION_PRESERVE_ALL_OUTPUTS', errorType=type(error).__name__, reason=str(error)[:1500])
    finally:
        if made:
            with (WORK / 'return.json').open('x') as stream: json.dump(report, stream, indent=2)
        print('BEGIN_NATIVE_RELEASE_REPORT'); print(json.dumps(report, indent=2)); print('END_NATIVE_RELEASE_REPORT')
    return 0 if report['status'] == 'CONTENT_OBSERVER_BINARIES_BUILT_TESTED_NOT_DEPLOYED' else 1


if __name__ == '__main__':
    raise SystemExit(main())
